  "ui.join_title": "Únete a {club}",
  "ui.your_name": "Tu nombre",
  "ui.join_language": "Idioma",
  "ui.club_news_consent": "Envíenme por correo las novedades y los eventos de {club}. Puedo dejar de recibirlos cuando quiera.",
  "ui.account_emails_note": "De todos modos recibirás correos sobre tus inscripciones, tus pagos y tu cuenta.",
  "ui.join_club": "Unirme",
  "error.sign_up_expired": "Pasó demasiado tiempo. Pide un código nuevo e inténtalo otra vez.",
  "cli.usage": "openpadel: configura y revisa el {product} de este club.\n  openpadel setup plan [club.yaml]    qué cambiaría al configurar el club con el archivo (no cambia nada)\n  openpadel setup apply [club.yaml]   hace esos cambios; vuelve a ejecutarlo después de editar el archivo\n  openpadel import members <archivo.csv> [--apply]   miembros desde una hoja de cálculo (una vista previa salvo con --apply)\n  openpadel doctor                    revisa que todo funcione, con el siguiente paso cuando algo falla\n  openpadel reset-sign-in <email>     empieza de nuevo el segundo paso del inicio de sesión de alguien (un teléfono perdido, un propietario sin acceso)\n  openpadel backup                    la copia de seguridad de esta noche, ahora: el volcado y su manifiesto, y la copia externa si está configurada\n  openpadel offsite                   lo que se guarda fuera\n  openpadel restore <archivo|offsite:latest> --yes   reemplaza la base de datos por una copia, o por la exportación de un club (con sudo, en una instalación de un servidor)\n  openpadel export [--out=<carpeta>]  todo lo que el club necesita para funcionar en otro lugar, en un archivo sellado con una frase que escribes\n  openpadel read-only on|off|status   el interruptor de quien aloja el club: todos entran y descargan sus datos; no se reserva ni se cobra nada nuevo\n  openpadel moved on [--to=<url>] | off | status   el club funciona en otro lado: este servidor no les envía nada a los miembros; antes de exportar\n  openpadel leaving on --date=AAAA-MM-DD [--kept-days=N] [--email-domain=<dominio> [--email-domain-host]] | off | status   el día en que termina el {product} del club; se le avisa al dueño que descargue todo antes, y qué pasa con el dominio del correo\n  openpadel held [send|drop] --yes      después de restaurar aquí la exportación de un club: lo que el servidor anterior quizá ya envió, retenido hasta que lo digas\n  openpadel pitr status               hasta cuándo llega el archivo para volver a un minuto, y si va al día\n  sudo openpadel restore --to=\"AAAA-MM-DD HH:MM\" --yes   la base de datos como estaba en ese minuto (hora del club), desde el archivo\n  openpadel restore-test              restaura la copia más reciente en una base de datos de prueba y la revisa\n  openpadel rotate-key                sella todos los secretos con KUMI_SECRET_KEY (la clave anterior en KUMI_SECRET_KEY_PREVIOUS)\n  openpadel texting plan|apply|status [club.yaml]   registra los mensajes de texto del club con las operadoras de EE. UU. desde su cuenta de Twilio (toll-free)\n  openpadel usage [--month=AAAA-MM]   lo que costaron la IA, los mensajes de texto y el correo este mes (o ese), frente al límite del club\n  sudo openpadel update <release.tar> | sudo openpadel rollback --yes | sudo openpadel releases   actualizar, en una instalación de un servidor\nAgrega --json para una salida que pueda leer un agente, y --lang=en para inglés.",
  "cli.usage_club": "Desde cualquier computadora: openpadel login <la dirección del club>, y luego openpadel help para los comandos del club.",
  "cli.club_usage": "openpadel: los comandos del club, desde cualquier computadora.\n  openpadel login <dirección>        inicia sesión en un club (la dirección de su app del personal o de miembros): se abre el navegador, o --device da un enlace y un código para permitirlo desde tu teléfono (--no-wait para terminar después)\n  openpadel whoami                   quién eres ahí, tus roles y lo que el límite de gasto te deja esta semana\n  openpadel clubs | openpadel use <dirección>   los clubes con sesión aquí, y a cuál van los comandos (o --club <dirección> en cualquier comando)\n  openpadel logout                   cierra la sesión aquí y termina la conexión en el club\n  openpadel <lectura> [opciones]     lee lo que muestran las apps (abajo)\n  openpadel <cosa> <cambio> [opciones]   muestra la vista previa del cambio y no cambia nada (código de salida 10)\n  openpadel confirm <run_id>         hace un cambio que viste antes, o vuelve a correr el comando con --yes\n  openpadel help <comando>           sus opciones y un ejemplo; openpadel schema <comando> para su esquema JSON\nCada comando acepta --json (un objeto JSON por línea), --lang=en y --club. Los nombres sirven donde van ids (--person \"María López\"), y una hora sin zona es en el reloj del club. En el servidor del club también están openpadel doctor, setup, backup y los demás (openpadel sin nada más los lista).",
