  "texting.edit_reason": "Datos corregidos después de la revisión.",
  "texting.use_case": "{club} es un club de pádel. Envía mensajes de texto a sus propios miembros, que dicen que sí en la app del club, solo sobre sus propias reservas y lugares: un lugar que se les abrió desde una lista de espera y que deben tomar antes de un plazo, o una reserva o clase que el club canceló o cambió. También envía códigos de un solo uso que una persona pide, para confirmar su número o para entrar. Nunca envía publicidad ni noticias del club por mensaje de texto.",
  "texting.opt_in_flow": "El consentimiento es un formulario web en la app del club (Perfil, Mensajes de texto). El miembro primero confirma su número móvil con un código, y luego marca una casilla sin marcar que dice: \"{consent}\" Cada sí se guarda con la hora, la versión del texto y el dispositivo. Responder STOP detiene todos los mensajes; HELP da el nombre del club y cómo contactarlo. Una página que muestra el formulario: {page}",
  "doctor.texts.no_sender": "Mensajes de texto: la cuenta de Twilio está, pero aún no hay desde dónde enviar. Registra un número toll-free con openpadel texting plan, o indica uno en KUMI_TWILIO_MESSAGING_SERVICE_SID (o KUMI_TWILIO_FROM).",
