  "msg.usage_near_staff.subject": "Uso: se usó el 80% del límite de este mes",
  "msg.usage_near_staff.body": "El club usó {spent} de su límite mensual de {cap} para IA, mensajes de texto y correo. Al llegar a {limit}, lo que puede esperar se pausa hasta el {resets}: los borradores en el otro idioma, los correos de noticias del club y los mensajes de texto que pueden llegar a los miembros en la app y por correo. Los códigos para iniciar sesión, las respuestas con la información del club, las confirmaciones y las cancelaciones siguen enviándose. Para cambiar el límite, ve a Uso.",
  "msg.usage_reached_staff.subject": "En pausa: se llegó al límite de este mes",
  "msg.usage_reached_staff.body": "El club usó su límite mensual de {cap} para IA, mensajes de texto y correo ({spent}). Hasta el {resets}, lo que puede esperar espera: no hay borradores en el otro idioma, los correos de noticias del club salen cuando empiece el mes, y los mensajes de texto que pueden esperar llegan a los miembros en la app y por correo. Los códigos para iniciar sesión, las respuestas con la información del club, las confirmaciones y las cancelaciones siguen enviándose. Para reanudar lo demás ya, sube el límite en Uso.",
  "msg.usage_over_staff.subject": "Se llegó al límite de este mes",
  "msg.usage_over_staff.body": "El club usó su límite mensual de {cap} para IA, mensajes de texto y correo ({spent}). Todo sigue hasta {limit}, con los {over} permitidos por encima del límite; pasado eso, lo que puede esperar se pausa hasta el {resets}. Para cambiar cualquiera de los dos, ve a Uso.",
  "msg.usage_paused_staff.subject": "En pausa: se usaron el límite de este mes y el monto por encima",
  "msg.usage_paused_staff.body": "El club usó {spent} este mes: su límite de {cap} y los {over} permitidos por encima. Hasta el {resets}, lo que puede esperar espera: no hay borradores en el otro idioma, los correos de noticias del club salen cuando empiece el mes, y los mensajes de texto que pueden esperar llegan a los miembros en la app y por correo. Los códigos para iniciar sesión, las respuestas con la información del club, las confirmaciones y las cancelaciones siguen enviándose. Para reanudar lo demás ya, sube el límite en Uso.",
  "error.drafts_paused": "Los borradores están en pausa hasta el mes que viene: se llegó al límite mensual del club. Escríbelo tú, o pídele al dueño que suba el límite en Uso.",
  "doctor.usage.month": "Uso este mes: {spent} del límite de {cap} del club para IA, mensajes de texto y correo ({share}%).",
