  "doctor.usage.gap": "El uso de este mes puede quedarse corto: el {date} se restauró una copia sin nada de donde pasar el registro de uso, así que lo que costaron la IA, los mensajes de texto y el correo después de hacerse la copia no está contado. openpadel usage --json lo muestra en gaps.",
